class Solution:
    def selfDividingNumbers(self, left: int, right: int) -> list[int]:
        result = []
        for number in range(left, right + 1):
            working = number
            while working:
                digit = working % 10
                if digit == 0 or number % digit:
                    break
                working //= 10
            if working == 0:
                result.append(number)
        return result
